<?php
require_once __DIR__.'/config.php'; session_start();
if(empty($_SESSION['user_id'])){header('Location: signin.php');exit;}
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$pdo=get_db_connection(); $events=[];
if($pdo){xinng_ensure_page_builder_tables($pdo);$stmt=$pdo->prepare('SELECT p.*,pe.start_at,pe.end_at,pe.venue,pe.city,(SELECT COUNT(*) FROM event_ticket_types t WHERE t.page_id=p.id AND t.deleted_at IS NULL) ticket_types,(SELECT COALESCE(SUM(o.quantity),0) FROM event_orders o WHERE o.page_id=p.id AND o.payment_status IN ("free","paid")) attendees FROM pages p LEFT JOIN page_events pe ON pe.page_id=p.id WHERE p.user_id=? AND p.page_type="event" AND p.deleted_at IS NULL ORDER BY pe.start_at IS NULL,pe.start_at,p.updated_at DESC');$stmt->execute([(int)$_SESSION['user_id']]);$events=$stmt->fetchAll();}
?>
