<main class="main"><header class="main-header"><div class="header-title"><h1>Events</h1><span>Create, sell tickets, register attendees, and run check-in.</span></div><a class="primary-btn header-create-page" href="pages.php?create=event"><i class="fa-solid fa-plus"></i>Create event</a></header><div class="content"><div class="events-wrap"><section class="events-hero"><span>EVENTS WORKSPACE</span><h2>Everything behind your event, in one place.</h2><p>Every event is a Xing Page with its own schedule, location, ticket inventory, registrations and check-in.</p></section><div class="events-list"><?php if(!$events):?><section class="events-empty"><i class="fa-solid fa-calendar-plus"></i><h2>No events yet</h2><p>Create an Event Page to get started.</p><a href="pages.php?create=event">Create your first event</a></section><?php endif;?><?php foreach($events as $event):$where=trim(($event['venue']??'').(($event['venue']??'')&&($event['city']??'')?', ':'').($event['city']??''));?><article class="event-row"><div class="event-date"><strong><?=!empty($event['start_at'])?e(date('d',strtotime($event['start_at']))):'--'?></strong><span><?=!empty($event['start_at'])?e(strtoupper(date('M',strtotime($event['start_at'])))):'DATE'?></span></div><div class="event-row-copy"><span class="event-status"><?=e(ucfirst($event['status']??'draft'))?></span><h3><?=e($event['title'])?></h3><p><i class="fa-regular fa-clock"></i> <?=!empty($event['start_at'])?e(date('M j, Y · g:i A',strtotime($event['start_at']))):'Date and time required'?> <i class="fa-solid fa-location-dot"></i> <?=e($where?:'Location required')?></p><div><span><?=number_format((int)$event['ticket_types'])?> ticket types</span><span><?=number_format((int)$event['attendees'])?> attendees</span></div></div><div class="event-row-actions"><a href="page_builder.php?id=<?=(int)$event['id']?>">Edit event</a><a href="event_orders.php?page_id=<?=(int)$event['id']?>">Attendees</a><a href="<?=e(xinng_short_url($event['slug']))?>" target="_blank">View</a></div></article><?php endforeach;?></div></div></div></main></div></body></html>
